import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.B8HA7oqK.js";var c=JSON.parse(`{"title":"Browser Dialer","description":"","frontmatter":{},"headers":[],"relativePath":"config/features/browser_dialer.md","filePath":"config/features/browser_dialer.md","lastUpdated":1768735895000}`),l={name:`config/features/browser_dialer.md`};function u(a,c,l,u,d,f){let p=e(`Badge`);return s(),n(`div`,null,[c[0]||=t(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /config/features/browser_dialer.md for this page in Markdown format</div><h1 id="browser-dialer" tabindex="-1">Browser Dialer <a class="header-anchor" href="#browser-dialer" aria-label="Permalink to “Browser Dialer”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>通过 uTLS，Xray 可以模拟主流浏览器的 TLS 握手指纹（具体参见 TLS 中 <code>fingerprint</code> 选项）。但是仍然不能保证在任意时刻 uTLS 模拟浏览器行为完全一致。</p><p>对此 <a href="https://github.com/v2ray/discussion/issues/754#issuecomment-647934994" target="_blank" rel="noreferrer">浏览器转发（browser dialer）</a>应运而生。用户在自己的浏览器中打开一个页面至 <code>localhost:8080</code>，这个页面利用原生 JS 充当 Xray 的网络栈，与代理服务端建立 TLS，HTTP 连接。</p><p>这个方法简洁的实现了真实的浏览器的 TLS 指纹、行为特征。最大程度抗检测与抗封锁。</p><p>不过目前的浏览器转发有以下缺点：</p><ul><li>用户需要手动开浏览器</li><li>浏览器发出的连接必须直连 使用 tun 的用户需要特别注意容易形成死循环</li><li>浏览器只能发出 HTTP 连接 所以目前仅支持 <a href="./../transports/websocket.html">WebSocket</a> 与 <a href="https://github.com/XTLS/Xray-core/discussions/4113" target="_blank" rel="noreferrer">XHTTP</a> 传输方式</li><li>当浏览器从 <code>localhost:8080</code> 页面连接至代理服务端，需要考虑 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a></li><li>因为中间经过 JS 处理数据，会有一些性能损耗</li><li>不能使用自定义 SNI 或者 Host，也就是说 <code>SNI == host == address</code>。自定义 HTTP 头以及其它 <code>tlsSettings</code> 项会被忽略</li></ul><h2 id="配置方法" tabindex="-1">配置方法 <a class="header-anchor" href="#配置方法" aria-label="Permalink to “配置方法”">​</a></h2><ol><li>准备一份 WebSocket 或 XHTTP 配置，注意 address 必须填域名，若需要指定 IP，请配置 DNS 或系统 hosts</li><li>使用环境变量启动 Xray <code>XRAY_BROWSER_DIALER=127.0.0.1:8080</code>。Windows 上命令为 <code>set XRAY_BROWSER_DIALER=127.0.0.1:8080</code> Linux 上命令为 <code>XRAY_BROWSER_DIALER=127.0.0.1:8080 ./xray -c config.json</code></li><li>确保浏览器直连（或者在路由中将服务端地址直接由 <code>freedom</code> 发出），打开页面 <code>localhost:8080</code>，还可以 <code>F12</code> 看 <code>Console</code> 和 <code>Network</code></li><li>浏览器会限制发出的连接数，所以建议开启 <code>Mux.Cool</code></li></ol><h2 id="内部通信机制" tabindex="-1">内部通信机制 <a class="header-anchor" href="#内部通信机制" aria-label="Permalink to “内部通信机制”">​</a></h2><ul><li>Xray 监听地址端口 <code>http://127.0.0.1:8080</code>，作为 HTTP 服务，浏览器访问地址，加载网页中的 JS。</li><li>JS 主动向 <code>http://127.0.0.1:8080</code> 建立 WebSocket 连接，成功后，Xray 将连接发给 channel。</li><li>需要建立连接时，Xray 从 channel 接收一个可用的连接，并发送目标 URL 和可选的 early data。</li><li>JS 成功连接到目标后告知 Xray，并继续用这个 conn 全双工双向转发数据，连接关闭行为同步。</li><li>连接使用后就会被关闭，但 JS 会确保始终有新空闲连接可用。</li></ul><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to “WebSocket”">​</a></h2>`,13),i(p,{text:`v1.4.1+`,type:`warning`}),c[1]||=t(`<p>根据浏览器的需求，对 early data 机制进行了如下调整：</p><ul><li>服务端响应头会带有请求的 <code>Sec-WebSocket-Protocol</code>，这也初步混淆了 WSS 握手响应的长度特征。</li><li>用于浏览器的 early data 编码是 <code>base64.RawURLEncoding</code> 而不是 <code>StdEncoding</code>，服务端做了兼容。</li><li>此外，由于 <a href="https://github.com/XTLS/Xray-core/pull/375" target="_blank" rel="noreferrer">Xray-core#375</a> 推荐 <code>?ed=2048</code>，这个 PR 顺便将服务端一处 <code>MaxHeaderBytes</code> 扩至了 4096。 <s>（虽然好像不改也没问题）</s></li></ul><h2 id="xhttp" tabindex="-1">XHTTP <a class="header-anchor" href="#xhttp" aria-label="Permalink to “XHTTP”">​</a></h2>`,3),i(p,{text:`v1.8.19+`,type:`warning`}),c[2]||=o(`p`,null,[o(`a`,{href:`https://github.com/XTLS/Xray-core/discussions/4113`,target:`_blank`,rel:`noreferrer`},`XHTTP`),r(` 本身支持 QUIC，如果想使用浏览器自己的 QUIC 网络栈，Chrome 可以在 `),o(`code`,null,`chrome://flags`),r(` 中设定。其它浏览器也有相关选项。`)],-1),c[3]||=o(`p`,null,[r(`原理上说 `),o(`code`,null,`tlsSettings`),r(` 项会被忽略，使用哪个 HTTP 版本将完全由浏览器决定。`)],-1)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};